"""Tests for the hair editor panel, drawn into a fake layout in background mode.

The panel is the one part of the hair editor no operator touches, and every mode and target draws a different
set of properties, so a typo in one of them would otherwise only show up as a broken panel in the UI.
"""

import itertools
import os

import bpy
import pytest

from ... import ObjectService
from .haireditor_fixtures import (mpfb_module, HairEditorService, hairproperties as hp, haircardservice as cg, HairCardService, haireditorpanel,
                                  toggle_section_operator, HAIR_PROPERTIES, scratch, character, hair_character,
                                  select, link, make_grid, FakeLayout, panel_instance, labels, drawn_props,
                                  drawn_flags, unfold_every_section, draw_asset_block)

Panel = haireditorpanel.MPFB_PT_Hair_Editor_Panel

_ASSET_NUMBERS = itertools.count()


# ---------------------------------------------------------------------------
# Where the panel shows up
# ---------------------------------------------------------------------------

def test_panel_shares_the_apply_assets_tab():
    assets_panel = mpfb_module("mpfb.ui.apply_assets.assetspanel").MPFB_PT_Assets_Panel
    assert Panel.bl_category == assets_panel.bl_category
    assert Panel.bl_order > getattr(assets_panel, "bl_order", 0), "the hair editor sits below Apply assets"


def test_panel_needs_a_character(scratch):
    ObjectService.deselect_and_deactivate_all()
    assert not Panel.poll(bpy.context)
    select(make_grid("panel_unrelated"))
    assert not Panel.poll(bpy.context)


def test_panel_shows_for_the_character(character):
    select(character)
    assert Panel.poll(bpy.context)


# ---------------------------------------------------------------------------
# Missing or outdated asset pack
# ---------------------------------------------------------------------------

def _draw_panel(monkeypatch, installed, outdated, character):
    monkeypatch.setattr(HairEditorService, "is_hair_asset_installed", staticmethod(lambda: installed))
    monkeypatch.setattr(HairEditorService, "is_hair_pack_outdated", staticmethod(lambda: outdated))
    monkeypatch.setattr(HairEditorService, "is_fur_asset_installed", staticmethod(lambda: installed))
    log = []
    panel = panel_instance(FakeLayout(log))
    drawn = []
    panel._hair_panel = lambda basemesh, layout: drawn.append("hair")
    panel._fur_panel = lambda basemesh, layout: drawn.append("fur")
    select(character)
    panel.draw(bpy.context)
    return log, drawn


def test_panel_without_the_asset_pack(character, monkeypatch):
    log, drawn = _draw_panel(monkeypatch, installed=False, outdated=False, character=character)
    assert "Hair editor assets are not" in labels(log)
    assert drawn == [], "nothing else can work without the assets"


def test_panel_warns_about_the_old_asset_pack(character, monkeypatch):
    log, drawn = _draw_panel(monkeypatch, installed=True, outdated=True, character=character)
    assert "Old hair editor asset pack" in labels(log)
    assert drawn == ["hair", "fur"], "an old pack still works, so the editor is drawn below the warning"
    assert labels(log).index("Old hair editor asset pack") == 0, "the warning comes first"


def test_panel_with_the_current_pack_does_not_warn(character, monkeypatch):
    log, drawn = _draw_panel(monkeypatch, installed=True, outdated=False, character=character)
    assert "Old hair editor asset pack" not in labels(log)
    assert drawn == ["hair", "fur"]


def test_panel_draws_nothing_without_a_character(scratch, monkeypatch):
    """poll() keeps this from happening, but a redraw can race the character being deleted."""
    log = []
    panel = panel_instance(FakeLayout(log))
    ObjectService.deselect_and_deactivate_all()
    panel.draw(bpy.context)
    assert log == []


# ---------------------------------------------------------------------------
# Bake section, for every target and lighting mode
# ---------------------------------------------------------------------------

@pytest.fixture
def bake_settings(character):
    """A character with the bake and generation settings of an asset, which is all the bake section reads."""
    asset = f"panelasset{next(_ASSET_NUMBERS)}_{os.getpid()}"
    hp.create_cards_config_properties(HAIR_PROPERTIES, character, asset)
    hp.create_cards_bake_properties(HAIR_PROPERTIES, character, asset)
    unfold_every_section(asset)
    yield character, asset
    toggle_section_operator.forget_asset(asset)
    HAIR_PROPERTIES.remove_dynamic_keys_with_prefix(f"{asset}_", character)


def _set(basemesh, asset, name, value):
    setattr(basemesh, f"{HAIR_PROPERTIES.dynamic_prefix}{asset}_{name}", value)


def _draw_bake_section(basemesh, asset, target=cg.BAKE_TARGET_CARDS, mode=cg.CARDS_MODE_TILES):
    _set(basemesh, asset, "cards_bake_target", target)
    if mode is not None:
        _set(basemesh, asset, "cards_mode", mode)
    log = []
    panel_instance()._bake_section(basemesh, FakeLayout(log), asset, HAIR_PROPERTIES, "hair", mode, target)
    return log


def _drew_prop(log, asset, name):
    return f"{HAIR_PROPERTIES.dynamic_prefix}{asset}_{name}" in drawn_props(log)


def _bake_button(log):
    return [name for kind, name in log if kind == "operator" and name == "mpfb.bake_hair_operator"]


@pytest.mark.parametrize("mode", [cg.LIGHT_MODE_FIXED, cg.LIGHT_MODE_BBOX, cg.LIGHT_MODE_NO_SHADOW,
                                  cg.LIGHT_MODE_ACROSS_STRANDS])
def test_bake_lights_offer_their_strength(bake_settings, mode):
    basemesh, asset = bake_settings
    _set(basemesh, asset, "cards_light_mode", mode)
    _set(basemesh, asset, "cards_light_strength", 0.5)
    log = _draw_bake_section(basemesh, asset)
    assert _drew_prop(log, asset, "cards_light_mode")
    assert _drew_prop(log, asset, "cards_light_strength")
    assert f"= {HairCardService.light_base_energy(mode) * 0.5:.0f} W per light" in labels(log)


def test_scene_lighting_has_no_strength_slider(bake_settings):
    """The scene's own lights keep their own wattage, so a strength slider would do nothing."""
    basemesh, asset = bake_settings
    _set(basemesh, asset, "cards_light_mode", cg.LIGHT_MODE_SCENE)
    log = _draw_bake_section(basemesh, asset)
    assert _drew_prop(log, asset, "cards_light_mode")
    assert not _drew_prop(log, asset, "cards_light_strength")
    assert not any(label.endswith("W per light") for label in labels(log))
    assert "The lights and the world of the scene" in labels(log)


def _rendered_lights():
    scene = bpy.context.scene
    return [obj for obj in scene.objects
            if obj.type == 'LIGHT' and HairEditorService.is_rendered(obj, scene, bpy.context.view_layer)]


def test_scene_lighting_counts_the_lights(bake_settings):
    basemesh, asset = bake_settings
    _set(basemesh, asset, "cards_light_mode", cg.LIGHT_MODE_SCENE)
    link(bpy.data.objects.new("panel_scene_light", bpy.data.lights.new("panel_scene_light", 'SUN')))
    log = _draw_bake_section(basemesh, asset)
    assert f"{len(_rendered_lights())} light(s) in the scene render" in labels(log)


def test_light_hidden_only_in_the_viewport_is_counted(bake_settings):
    """It still lights the bake, so the panel must not claim there are no lights."""
    basemesh, asset = bake_settings
    _set(basemesh, asset, "cards_light_mode", cg.LIGHT_MODE_SCENE)
    others = _rendered_lights()
    for light in others:
        light.hide_render = True
    light = link(bpy.data.objects.new("panel_viewport_hidden", bpy.data.lights.new("panel_viewport_hidden", 'SUN')))
    light.hide_set(True)
    try:
        assert "1 light(s) in the scene render" in labels(_draw_bake_section(basemesh, asset))
    finally:
        for other in others:
            other.hide_render = False


def test_scene_lighting_warns_without_lights(bake_settings):
    basemesh, asset = bake_settings
    _set(basemesh, asset, "cards_light_mode", cg.LIGHT_MODE_SCENE)
    hidden = _rendered_lights()
    for light in hidden:
        light.hide_render = True
    try:
        log = _draw_bake_section(basemesh, asset)
        assert "No light in the scene is enabled for render," in labels(log)
    finally:
        for light in hidden:
            light.hide_render = False


@pytest.mark.parametrize("mode, offered", [(cg.LIGHT_MODE_FIXED, True), (cg.LIGHT_MODE_BBOX, True),
                                           (cg.LIGHT_MODE_SCENE, True), (cg.LIGHT_MODE_NO_SHADOW, False),
                                           (cg.LIGHT_MODE_ACROSS_STRANDS, False)])
def test_body_shadows_are_offered_where_lights_cast(bake_settings, mode, offered):
    basemesh, asset = bake_settings
    _set(basemesh, asset, "cards_light_mode", mode)
    assert ("cards_body_shadows" in drawn_flags(_draw_bake_section(basemesh, asset))) == offered


def test_diffuse_bake_has_no_lighting(bake_settings):
    basemesh, asset = bake_settings
    _set(basemesh, asset, "cards_glossy", False)
    log = _draw_bake_section(basemesh, asset)
    assert "The diffuse pass bakes unlit albedo, so" in labels(log)
    assert not _drew_prop(log, asset, "cards_light_mode")
    assert not _drew_prop(log, asset, "cards_light_strength")
    assert "cards_body_shadows" not in drawn_flags(log)


def test_cards_offer_texture_sharing(bake_settings):
    basemesh, asset = bake_settings
    log = _draw_bake_section(basemesh, asset)
    assert "cards_atlas_enabled" in drawn_flags(log)
    assert "cards_analytic_uvs" in drawn_flags(log)
    assert not _drew_prop(log, asset, "cards_atlas_fraction"), "the fraction only shows once sharing is on"
    _set(basemesh, asset, "cards_atlas_enabled", True)
    assert _drew_prop(_draw_bake_section(basemesh, asset), asset, "cards_atlas_fraction")
    assert _bake_button(log)


def test_tighter_packing_is_the_generated_layout_and_the_default(bake_settings):
    """Pack UVs tighter is cards_analytic_uvs - the generator's own layout fills the atlas cells completely."""
    basemesh, asset = bake_settings
    tighter = "Tighter UV packing uses the texture space"
    assert tighter in labels(_draw_bake_section(basemesh, asset))
    _set(basemesh, asset, "cards_analytic_uvs", False)
    assert tighter not in labels(_draw_bake_section(basemesh, asset))


def test_shell_offers_no_texture_sharing(bake_settings):
    """The shell is one connected piece, there is nothing to share a texture between."""
    basemesh, asset = bake_settings
    log = _draw_bake_section(basemesh, asset, mode=cg.CARDS_MODE_SHELL)
    assert "cards_atlas_enabled" not in drawn_flags(log)
    assert "Side on and Root tip are always baked" in labels(log)
    assert "cards_bake_side_on" not in drawn_flags(log), "a forced map must not look optional"


@pytest.mark.parametrize("target, note", [(cg.BAKE_TARGET_BODY_DIRECT, "Baked 1:1 into the body's own UV layout."),
                                          (cg.BAKE_TARGET_CUSTOM, "Baked 1:1 into the mesh's own UV layout,"),
                                          (cg.BAKE_TARGET_BODY_SHELL, "Baked into the shell's copy of the body UVs,")])
def test_other_targets_bake_into_their_own_layout(bake_settings, target, note):
    basemesh, asset = bake_settings
    log = _draw_bake_section(basemesh, asset, target=target, mode=None)
    assert note in labels(log)
    assert "cards_atlas_enabled" not in drawn_flags(log)
    assert _bake_button(log)


@pytest.mark.parametrize("target", [cg.BAKE_TARGET_BODY_DIRECT, cg.BAKE_TARGET_BODY_SHELL])
def test_body_targets_always_limit_the_rays(bake_settings, target):
    basemesh, asset = bake_settings
    log = _draw_bake_section(basemesh, asset, target=target, mode=None)
    assert "cards_limit_ray_range" not in drawn_flags(log), "a forced setting must not look optional"
    assert _drew_prop(log, asset, "cards_ray_range")


def test_body_texture_is_captured_from_one_side_only(bake_settings):
    basemesh, asset = bake_settings
    log = _draw_bake_section(basemesh, asset, target=cg.BAKE_TARGET_BODY_DIRECT, mode=None)
    assert "cards_double_sided" not in drawn_flags(log)


def test_ray_range_shows_when_it_is_used(bake_settings):
    basemesh, asset = bake_settings
    assert not _drew_prop(_draw_bake_section(basemesh, asset), asset, "cards_ray_range")
    _set(basemesh, asset, "cards_limit_ray_range", True)
    assert _drew_prop(_draw_bake_section(basemesh, asset), asset, "cards_ray_range")
    _set(basemesh, asset, "cards_limit_ray_range", False)
    _set(basemesh, asset, "cards_bake_depth", True)
    assert _drew_prop(_draw_bake_section(basemesh, asset), asset, "cards_ray_range"), \
        "the depth map is scaled by the ray range"


@pytest.mark.parametrize("fade, width, warned", [(False, 2, False), (True, 1, False), (True, 4, True)])
def test_body_shell_edge_fade(bake_settings, fade, width, warned):
    basemesh, asset = bake_settings
    _set(basemesh, asset, "cards_body_edge_fade", fade)
    _set(basemesh, asset, "cards_body_edge_fade_width", width)
    log = _draw_bake_section(basemesh, asset, target=cg.BAKE_TARGET_BODY_SHELL, mode=None)
    assert "cards_body_edge_fade" in drawn_flags(log)
    assert _drew_prop(log, asset, "cards_body_edge_fade_width") == fade
    assert any(label.startswith("Fade is wider than Face dilation") for label in labels(log)) == warned


def test_double_sided_note_depends_on_the_target(bake_settings):
    basemesh, asset = bake_settings
    _set(basemesh, asset, "cards_double_sided", True)
    assert "Pass starts just outside the skin" in labels(
        _draw_bake_section(basemesh, asset, target=cg.BAKE_TARGET_BODY_SHELL, mode=None))
    assert "Meant for the cluster modes: on tiles and" in labels(_draw_bake_section(basemesh, asset))


def test_object_space_normals_are_pointed_out(bake_settings):
    basemesh, asset = bake_settings
    _set(basemesh, asset, "cards_bake_normal", True)
    assert "Normal map is OBJECT space, not tangent space" in labels(_draw_bake_section(basemesh, asset))


