def test_asset_block_starts_closed(hair_character):
    log = []
    panel_instance()._asset_block(hair_character.basemesh, FakeLayout(log), hair_character.asset_name, False)
    assert len(log) == 1, "a closed asset block draws only its own toggle"


def test_asset_block_before_conversion(hair_character):
    log = draw_asset_block(hair_character)
    assert ("operator", "mpfb.generate_hair_cards_operator") in log
    assert ("operator", "mpfb.delete_hair_operator") in log
    assert ("operator", "mpfb.bake_hair_operator") not in log, "there is nothing to bake before the cards exist"
    for name in hp.DYNAMIC_HAIR_PROPS_DEFINITIONS:
        assert f"DHAI_{hair_character.asset_name}_{name}" in drawn_props(log), f"slider {name} is missing"


def test_whole_panel_draws_with_an_asset(hair_character):
    log = []
    select(hair_character.basemesh)
    panel_instance(FakeLayout(log)).draw(bpy.context)
    assert "Hair assets:" in labels(log)
    assert ("operator", "mpfb.apply_hair_operator") in log


@pytest.mark.parametrize("mode", [item[0] for item in cg.CARDS_MODE_ITEMS])
@pytest.mark.parametrize("selection", [item[0] for item in cg.SELECTION_METHOD_ITEMS])
def test_asset_block_draws_for_every_mode(hair_character, mode, selection):
    hair_character.run("generate_hair_cards_operator")
    hair_character.set("cards_mode", mode)
    hair_character.set("cards_selection_method", selection)
    log = draw_asset_block(hair_character)
    assert ("operator", "mpfb.regenerate_hair_cards_operator") in log
    assert ("operator", "mpfb.bake_hair_operator") in log


@pytest.mark.parametrize("target", [item[0] for item in cg.BAKE_TARGET_ITEMS])
def test_asset_block_draws_for_every_target(hair_character, target):
    hair_character.set("cards_bake_target", target)
    log = draw_asset_block(hair_character)
    assert len(log) > 5
    assert ("operator", "mpfb.delete_hair_operator") in log


def test_custom_target_asks_for_a_mesh(hair_character):
    hair_character.set("cards_bake_target", cg.BAKE_TARGET_CUSTOM)
    assert ("operator", "mpfb.bake_hair_operator") not in draw_asset_block(hair_character)
    target = make_grid("panel_custom_target")
    hair_character.set("cards_custom_mesh", target.name)
    assert ("operator", "mpfb.bake_hair_operator") in draw_asset_block(hair_character)


def test_body_texture_needs_a_skin_material(hair_character):
    hair_character.set("cards_bake_target", cg.BAKE_TARGET_BODY_DIRECT)
    materials = [slot.material for slot in hair_character.basemesh.material_slots]
    hair_character.basemesh.data.materials.clear()
    try:
        log = draw_asset_block(hair_character)
        assert "Apply a skin material first." in labels(log)
        assert ("operator", "mpfb.bake_hair_operator") not in log
    finally:
        for material in materials:
            hair_character.basemesh.data.materials.append(material)
